function cx(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(' ');
}

function initials(name?: string) {
  return (name || 'RC').split(' ').slice(0, 2).map((part) => part[0]).join('').toUpperCase();
}

function Spinner({ label = 'Working' }: { label?: string }) {
  return <span className="inline-flex items-center gap-2 text-sm text-muted-foreground"><RefreshCw className="size-4 animate-spin" />{label}</span>;
}

function EmptyState({ icon: Icon, title, message, action }: { icon: Icon; title: string; message: string; action?: ReactNode }) {
  return <div className="empty-state">
    <div className="empty-icon"><Icon className="size-6" /></div>
    <h3 className="font-display text-lg font-semibold">{title}</h3>
    <p className="max-w-sm text-sm leading-6 text-muted-foreground">{message}</p>
    {action}
  </div>;
}

function LoadingRows({ count = 4 }: { count?: number }) {
  return <div className="space-y-3" aria-label="Loading content">{Array.from({ length: count }).map((_, i) => <div key={i} className="skeleton h-16 rounded-xl" />)}</div>;
}

function QueryState({ loading, error, children, empty, onRetry }: { loading?: boolean; error?: unknown; children: ReactNode; empty?: boolean; onRetry?: () => void }) {
  if (loading) return <LoadingRows />;
  if (error) return <div className="rounded-2xl border border-destructive/25 bg-destructive/5 p-7 text-center"><X className="mx-auto mb-3 size-7 text-destructive" /><h3 className="font-semibold">Could not load this yet</h3><p className="mt-1 text-sm text-muted-foreground">The academic service may be taking a breather.</p><button data-testid="button-retry" onClick={onRetry} className="mt-4 inline-flex items-center gap-2 rounded-lg border bg-background px-4 py-2 text-sm font-semibold"><RefreshCw className="size-4" />Try again</button></div>;
  if (empty) return <EmptyState icon={LibraryBig} title="A quiet shelf for now" message="There is nothing here yet. Check back after the next resource update." />;
  return <>{children}</>;
}

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link href="/" data-testid="link-brand" className="flex items-center gap-3">
    <div className="brand-mark"><span>↗</span></div>
    {!compact && <div><div className="font-display text-[17px] font-bold leading-none tracking-tight">StudyMate</div><div className="mt-1 text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/55">RCPIT · Shirpur</div></div>}
  </Link>;
}

