function Avatar({ name, small = false }: { name?: string; small?: boolean }) {
  return <div data-testid="img-avatar" className={cx('avatar', small && 'avatar-small')}>{initials(name)}</div>;
}

function PageIntro({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="eyebrow">{eyebrow || 'StudyMate'}</div><h1 data-testid={`text-page-title-${title.toLowerCase().replaceAll(' ', '-')}`} className="mt-2 font-display text-3xl font-bold tracking-[-.04em] text-foreground sm:text-[38px]">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function StatCard({ label, value, meta, icon: Icon, tone = 'teal' }: { label: string; value: string | number; meta?: string; icon: Icon; tone?: string }) {
  return <div className="stat-card"><div className={cx('stat-icon', tone)}><Icon className="size-[18px]" /></div><div className="mt-5 text-2xl font-bold tracking-tight">{value}</div><div className="mt-1 text-xs font-semibold text-muted-foreground">{label}</div>{meta && <div className="mt-3 text-[11px] text-muted-foreground">{meta}</div>}</div>;
}

